INSERT INTO phrases (phrase_id,lesson_id,english_text,vietnamese_meaning,ipa_phonetic,audio_sample_url,context_note) VALUES
(10104, 101, 'Hello! I have an appointment here today.', 'Xin chào! Hôm nay tôi có lịch hẹn ở đây.', '/hɛˈloʊ! aɪ hæv ən əˈpɔɪntmənt hir təˈdeɪ/', '', 'PRACTICE_SENTENCE'),
(10105, 101, 'Thank you. Where is the meeting room?', 'Cảm ơn. Phòng họp ở đâu?', '/θæŋk ju. wɛr ɪz ðə ˈmitɪŋ rum/', '', 'PRACTICE_SENTENCE'),
(10106, 101, 'Please follow me to the meeting room.', 'Mời anh theo tôi đến phòng họp.', '/pliz ˈfɑloʊ mi tə ðə ˈmitɪŋ rum/', '', 'PRACTICE_SENTENCE'),
(10107, 101, 'Could I have some water, please?', 'Cho tôi xin chút nước nhé?', '/kʊd aɪ hæv səm ˈwɔtər, pliz/', '', 'PRACTICE_SENTENCE'),
(10108, 101, 'Of course. Please take a seat.', 'Được ạ. Mời anh ngồi.', '/əv kɔrs. pliz teɪk ə sit/', '', 'PRACTICE_SENTENCE'),
(10109, 101, 'Thank you for your help.', 'Cảm ơn bạn đã giúp đỡ.', '/θæŋk ju fər jʊr hɛlp/', '', 'PRACTICE_SENTENCE'),
(10110, 101, 'You are welcome.', 'Không có gì ạ.', '/ju ər ˈwɛlkəm/', '', 'PRACTICE_SENTENCE'),
(10204, 102, 'What matters most to you when choosing a service?', 'Điều gì quan trọng nhất khi anh/chị chọn dịch vụ?', '/wət ˈmætərz moʊst tə ju wɪn ˈʧuzɪŋ ə ˈsərvɪs/', '', 'PRACTICE_SENTENCE'),
(10205, 102, 'Do you have a particular goal in mind?', 'Anh/chị có mục tiêu cụ thể nào không?', '/du ju hæv ə ˌpɑˈtɪkjələr goʊl ɪn maɪnd/', '', 'PRACTICE_SENTENCE'),
(10206, 102, 'What challenges are you facing at the moment?', 'Hiện anh/chị đang gặp những khó khăn nào?', '/wət ˈʧælənʤɪz ər ju ˈfeɪsɪŋ æt ðə ˈmoʊmənt/', '', 'PRACTICE_SENTENCE'),
(10207, 102, 'Is this for personal or business use?', 'Anh/chị dùng cho cá nhân hay công việc?', '/ɪz ðɪs fər ˈpərsɪnəl ər ˈbɪznɪs juz/', '', 'PRACTICE_SENTENCE'),
(10208, 102, 'When would you like to get started?', 'Anh/chị muốn bắt đầu khi nào?', '/wɪn wʊd ju laɪk tə gɪt ˈstɑrtɪd/', '', 'PRACTICE_SENTENCE'),
(10209, 102, 'Let me make sure I understand your needs.', 'Để tôi chắc chắn mình hiểu nhu cầu của anh/chị.', '/lɛt mi meɪk ʃʊr aɪ ˌəndərˈstænd jʊr nidz/', '', 'PRACTICE_SENTENCE'),
(10210, 102, 'Please tell me if I have missed anything.', 'Vui lòng cho tôi biết nếu tôi bỏ sót điều gì.', '/pliz tɛl mi ɪf aɪ hæv mɪst ˈɛniˌθɪŋ/', '', 'PRACTICE_SENTENCE'),
(10303, 103, 'Would you like a written quotation?', 'Anh/chị muốn nhận báo giá bằng văn bản không?', '/wʊd ju laɪk ə ˈrɪtən kwoʊˈteɪʃən/', '', 'PRACTICE_SENTENCE'),
(10304, 103, 'The price depends on the services you choose.', 'Giá phụ thuộc vào dịch vụ anh/chị chọn.', '/ðə praɪs dɪˈpɛndz ɔn ðə ˈsərvɪsɪz ju ʧuz/', '', 'PRACTICE_SENTENCE'),
(10305, 103, 'This option may suit your budget better.', 'Lựa chọn này có thể phù hợp ngân sách hơn.', '/ðɪs ˈɔpʃən meɪ sut jʊr ˈbəʤɪt ˈbɛtər/', '', 'PRACTICE_SENTENCE'),
(10306, 103, 'There are no additional fees for this service.', 'Dịch vụ này không có phí bổ sung.', '/ðɛr ər noʊ əˈdɪʃənəl fiz fər ðɪs ˈsərvɪs/', '', 'PRACTICE_SENTENCE'),
(10307, 103, 'Let me explain what is included in the package.', 'Để tôi giải thích các hạng mục trong gói.', '/lɛt mi ɪkˈspleɪn wət ɪz ˌɪnˈkludɪd ɪn ðə ˈpækɪʤ/', '', 'PRACTICE_SENTENCE'),
(10308, 103, 'Would you like to compare the two plans?', 'Anh/chị muốn so sánh hai gói không?', '/wʊd ju laɪk tə kəmˈpɛr ðə tu plænz/', '', 'PRACTICE_SENTENCE'),
(10309, 103, 'Please review the terms before making a decision.', 'Vui lòng xem các điều khoản trước khi quyết định.', '/pliz ˌrivˈju ðə tərmz ˌbiˈfɔr ˈmeɪkɪŋ ə dɪˈsɪʒən/', '', 'PRACTICE_SENTENCE'),
(10310, 103, 'I can send the details to your email address.', 'Tôi có thể gửi thông tin đến địa chỉ email của anh/chị.', '/aɪ kən sɛnd ðə ˈditeɪlz tə jʊr iˈmeɪl ˈæˌdrɛs/', '', 'PRACTICE_SENTENCE'),
(10403, 104, 'Which part of the price concerns you most?', 'Phần giá nào khiến anh/chị băn khoăn nhất?', '/wɪʧ pɑrt əv ðə praɪs kənˈsərnz ju moʊst/', '', 'PRACTICE_SENTENCE'),
(10404, 104, 'Would a smaller package meet your needs?', 'Một gói nhỏ hơn có đáp ứng nhu cầu không?', '/wʊd ə sˈmɔlər ˈpækɪʤ mit jʊr nidz/', '', 'PRACTICE_SENTENCE'),
(10405, 104, 'We can discuss a more affordable option.', 'Chúng ta có thể trao đổi một lựa chọn tiết kiệm hơn.', '/wi kən dɪˈskəs ə mɔr əˈfɔrdəbəl ˈɔpʃən/', '', 'PRACTICE_SENTENCE'),
(10406, 104, 'Take your time to consider the offer.', 'Anh/chị cứ dành thời gian cân nhắc đề nghị.', '/teɪk jʊr taɪm tə kənˈsɪdər ðə ˈɔfər/', '', 'PRACTICE_SENTENCE'),
(10407, 104, 'I can explain how this service may help you.', 'Tôi có thể giải thích dịch vụ này giúp anh/chị như thế nào.', '/aɪ kən ɪkˈspleɪn haʊ ðɪs ˈsərvɪs meɪ hɛlp ju/', '', 'PRACTICE_SENTENCE'),
(10408, 104, 'Is there a budget you would like us to work within?', 'Anh/chị muốn chúng tôi làm trong mức ngân sách nào?', '/ɪz ðɛr ə ˈbəʤɪt ju wʊd laɪk ˈjuˈɛs tə wərk wɪˈθɪn/', '', 'PRACTICE_SENTENCE'),
(10409, 104, 'Would you like to compare the benefits first?', 'Anh/chị muốn so sánh quyền lợi trước không?', '/wʊd ju laɪk tə kəmˈpɛr ðə ˈbɛnəfɪts fərst/', '', 'PRACTICE_SENTENCE'),
(10410, 104, 'Please let me know if you have any other questions.', 'Vui lòng cho tôi biết nếu anh/chị còn câu hỏi khác.', '/pliz lɛt mi noʊ ɪf ju hæv ˈɛni ˈəðər kˈwɛsʧənz/', '', 'PRACTICE_SENTENCE'),
(10507, 105, 'Hello. I would like to buy a gift.', 'Xin chào. Tôi muốn mua một món quà.', '/hɛˈloʊ. aɪ wʊd laɪk tə baɪ ə gɪft/', '', 'PRACTICE_SENTENCE'),
(10508, 105, 'I am looking for something special.', 'Tôi đang tìm một món đặc biệt.', '/aɪ æm ˈlʊkɪŋ fər ˈsəmθɪŋ ˈspɛʃəl/', '', 'PRACTICE_SENTENCE'),
(10509, 105, 'It is for my sister.', 'Món quà dành cho chị gái tôi.', '/ɪt ɪz fər maɪ ˈsɪstər/', '', 'PRACTICE_SENTENCE'),
(10510, 105, 'My budget is fifty dollars.', 'Ngân sách của tôi là năm mươi đô la.', '/maɪ ˈbəʤɪt ɪz ˈfɪfti ˈdɔlərz/', '', 'PRACTICE_SENTENCE'),
(10511, 105, 'Thank you. Let me show you some options.', 'Cảm ơn. Để tôi cho anh/chị xem vài lựa chọn.', '/θæŋk ju. lɛt mi ʃoʊ ju səm ˈɔpʃənz/', '', 'PRACTICE_SENTENCE'),
(10512, 105, 'Are you buying this for yourself or someone else?', 'Anh/chị mua món này cho mình hay cho người khác?', '/ər ju baɪɪŋ ðɪs fər ˈjɔrsɛlf ər ˈsəmˌwən ɛls/', '', 'PRACTICE_SENTENCE'),
(10513, 105, 'Would you prefer something practical or decorative?', 'Anh/chị thích món hữu dụng hay món trang trí hơn?', '/wʊd ju prɪˈfər ˈsəmθɪŋ ˈpræktɪkəl ər ˈdɛkrətɪv/', '', 'PRACTICE_SENTENCE'),
(10607, 106, 'What is this bag made of?', 'Chiếc túi này làm từ gì?', '/wət ɪz ðɪs bæg meɪd əv/', '', 'PRACTICE_SENTENCE'),
(10608, 106, 'Is it comfortable to carry?', 'Mang túi này có thoải mái không?', '/ɪz ɪt ˈkəmfərtəbəl tə ˈkɛri/', '', 'PRACTICE_SENTENCE'),
(10609, 106, 'Can I try it?', 'Tôi có thể thử không?', '/kən aɪ traɪ ɪt/', '', 'PRACTICE_SENTENCE'),
(10610, 106, 'Thank you. It feels comfortable.', 'Cảm ơn. Mang rất thoải mái.', '/θæŋk ju. ɪt filz ˈkəmfərtəbəl/', '', 'PRACTICE_SENTENCE'),
(10611, 106, 'You are welcome. Take your time.', 'Không có gì. Anh/chị cứ từ từ xem.', '/ju ər ˈwɛlkəm. teɪk jʊr taɪm/', '', 'PRACTICE_SENTENCE'),
(10612, 106, 'You can open this pocket to store your phone.', 'Anh/chị có thể mở ngăn này để cất điện thoại.', '/ju kən ˈoʊpən ðɪs ˈpɑkət tə stɔr jʊr foʊn/', '', 'PRACTICE_SENTENCE'),
(10613, 106, 'Let me show you how the strap adjusts.', 'Để tôi chỉ cách điều chỉnh dây đeo.', '/lɛt mi ʃoʊ ju haʊ ðə stræp əˈʤəsts/', '', 'PRACTICE_SENTENCE'),
(10707, 107, 'How much is this item?', 'Món này giá bao nhiêu?', '/haʊ məʧ ɪz ðɪs ˈaɪtəm/', '', 'PRACTICE_SENTENCE'),
(10708, 107, 'Does that include tax?', 'Giá đã bao gồm thuế chưa?', '/dɪz ðət ˌɪnˈklud tæks/', '', 'PRACTICE_SENTENCE'),
(10709, 107, 'Can you offer a discount?', 'Bạn có thể giảm giá không?', '/kən ju ˈɔfər ə ˈdɪskaʊnt/', '', 'PRACTICE_SENTENCE'),
(10710, 107, 'That sounds good.', 'Nghe hợp lý đấy.', '/ðət saʊnz gʊd/', '', 'PRACTICE_SENTENCE'),
(10711, 107, 'Would you like to purchase it?', 'Anh/chị có muốn mua không?', '/wʊd ju laɪk tə ˈpərʧəs ɪt/', '', 'PRACTICE_SENTENCE'),
(10712, 107, 'The discount will be shown on your receipt.', 'Khoản giảm giá sẽ được ghi trên biên lai.', '/ðə ˈdɪskaʊnt wɪl bi ʃoʊn ɔn jʊr rɪˈsit/', '', 'PRACTICE_SENTENCE'),
(10713, 107, 'Would you like me to calculate the total?', 'Anh/chị muốn tôi tính tổng tiền không?', '/wʊd ju laɪk mi tə ˈkælkjəˌleɪt ðə ˈtoʊtəl/', '', 'PRACTICE_SENTENCE'),
(10807, 108, 'I would like to buy this one.', 'Tôi muốn mua món này.', '/aɪ wʊd laɪk tə baɪ ðɪs wən/', '', 'PRACTICE_SENTENCE'),
(10808, 108, 'Just one, please.', 'Một chiếc thôi nhé.', '/ʤɪst wən, pliz/', '', 'PRACTICE_SENTENCE'),
(10809, 108, 'I will pay by card.', 'Tôi sẽ thanh toán bằng thẻ.', '/aɪ wɪl peɪ baɪ kɑrd/', '', 'PRACTICE_SENTENCE'),
(10810, 108, 'Thank you for your help.', 'Cảm ơn bạn đã giúp đỡ.', '/θæŋk ju fər jʊr hɛlp/', '', 'PRACTICE_SENTENCE'),
(10811, 108, 'You are welcome. Have a nice day!', 'Không có gì. Chúc anh/chị một ngày tốt lành!', '/ju ər ˈwɛlkəm. hæv ə nis deɪ/', '', 'PRACTICE_SENTENCE'),
(10812, 108, 'Please check that the quantity is correct.', 'Vui lòng kiểm tra số lượng đã đúng chưa.', '/pliz ʧɛk ðət ðə kˈwɑntəti ɪz kərˈɛkt/', '', 'PRACTICE_SENTENCE'),
(10813, 108, 'Would you like a paper bag for your purchase?', 'Anh/chị muốn túi giấy để đựng hàng không?', '/wʊd ju laɪk ə ˈpeɪpər bæg fər jʊr ˈpərʧəs/', '', 'PRACTICE_SENTENCE'),
(10907, 109, 'I would like to return this bag.', 'Tôi muốn trả lại chiếc túi này.', '/aɪ wʊd laɪk tə rɪˈtərn ðɪs bæg/', '', 'PRACTICE_SENTENCE'),
(10908, 109, 'Yes, here is my receipt.', 'Có, đây là biên lai của tôi.', '/jɛs, hir ɪz maɪ rɪˈsit/', '', 'PRACTICE_SENTENCE'),
(10909, 109, 'I would prefer a refund.', 'Tôi muốn được hoàn tiền.', '/aɪ wʊd prɪˈfər ə ˈriˌfənd/', '', 'PRACTICE_SENTENCE'),
(10910, 109, 'Can you tell me if that is possible?', 'Bạn cho tôi biết có được không nhé?', '/kən ju tɛl mi ɪf ðət ɪz ˈpɑsəbəl/', '', 'PRACTICE_SENTENCE'),
(10911, 109, 'I will check the policy and explain your options.', 'Tôi sẽ kiểm tra chính sách và giải thích các lựa chọn.', '/aɪ wɪl ʧɛk ðə ˈpɑləsi ənd ɪkˈspleɪn jʊr ˈɔpʃənz/', '', 'PRACTICE_SENTENCE'),
(10912, 109, 'When did you purchase the item?', 'Anh/chị mua món hàng này khi nào?', '/wɪn dɪd ju ˈpərʧəs ðə ˈaɪtəm/', '', 'PRACTICE_SENTENCE'),
(10913, 109, 'Is there a problem with the product?', 'Sản phẩm có vấn đề gì không?', '/ɪz ðɛr ə ˈprɑbləm wɪθ ðə ˈprɑdəkt/', '', 'PRACTICE_SENTENCE'),
(11007, 110, 'I would like to try this shirt.', 'Tôi muốn thử chiếc áo này.', '/aɪ wʊd laɪk tə traɪ ðɪs ʃərt/', '', 'PRACTICE_SENTENCE'),
(11008, 110, 'Medium, please. Do you have it in blue?', 'Cỡ vừa nhé. Có màu xanh không?', '/ˈmidiəm, pliz. du ju hæv ɪt ɪn blu/', '', 'PRACTICE_SENTENCE'),
(11009, 110, 'Yes, blue would be great. Where can I try it?', 'Có, màu xanh rất hợp. Tôi thử ở đâu?', '/jɛs, blu wʊd bi greɪt. wɛr kən aɪ traɪ ɪt/', '', 'PRACTICE_SENTENCE'),
(11010, 110, 'Thank you. I will try it on.', 'Cảm ơn. Tôi sẽ thử.', '/θæŋk ju. aɪ wɪl traɪ ɪt ɔn/', '', 'PRACTICE_SENTENCE'),
(11011, 110, 'Let me know if you need another size.', 'Hãy cho tôi biết nếu anh/chị cần cỡ khác.', '/lɛt mi noʊ ɪf ju nid əˈnəðər saɪz/', '', 'PRACTICE_SENTENCE'),
(11012, 110, 'Does the shirt feel comfortable around your shoulders?', 'Phần vai áo có vừa và thoải mái không?', '/dɪz ðə ʃərt fil ˈkəmfərtəbəl əraʊnd jʊr ˈʃoʊldərz/', '', 'PRACTICE_SENTENCE'),
(11013, 110, 'We also have the same style in a larger size.', 'Chúng tôi cũng có kiểu này ở cỡ lớn hơn.', '/wi ˈɔlsoʊ hæv ðə seɪm staɪl ɪn ə ˈlɑrʤər saɪz/', '', 'PRACTICE_SENTENCE'),
(11107, 111, 'Do you have this camera?', 'Bạn có máy ảnh này không?', '/du ju hæv ðɪs ˈkæmərə/', '', 'PRACTICE_SENTENCE'),
(11108, 111, 'Thank you. Is the black model available?', 'Cảm ơn. Mẫu màu đen còn không?', '/θæŋk ju. ɪz ðə blæk ˈmɑdəl əˈveɪləbəl/', '', 'PRACTICE_SENTENCE'),
(11109, 111, 'That is a pity. What else would you recommend?', 'Tiếc quá. Bạn gợi ý mẫu nào khác?', '/ðət ɪz ə ˈpɪti. wət ɛls wʊd ju ˌrɛkəˈmɛnd/', '', 'PRACTICE_SENTENCE'),
(11110, 111, 'Yes, please show me.', 'Có, cho tôi xem nhé.', '/jɛs, pliz ʃoʊ mi/', '', 'PRACTICE_SENTENCE'),
(11111, 111, 'This one has similar features.', 'Mẫu này có tính năng tương tự.', '/ðɪs wən həz ˈsɪmələr ˈfiʧərz/', '', 'PRACTICE_SENTENCE'),
(11112, 111, 'Would you like us to contact you when it is available?', 'Anh/chị muốn chúng tôi liên hệ khi có hàng không?', '/wʊd ju laɪk ˈjuˈɛs tə ˈkɑnˌtækt ju wɪn ɪt ɪz əˈveɪləbəl/', '', 'PRACTICE_SENTENCE'),
(11113, 111, 'We may have another colour in stock.', 'Chúng tôi có thể còn màu khác trong kho.', '/wi meɪ hæv əˈnəðər ˈkələr ɪn stɑk/', '', 'PRACTICE_SENTENCE'),
(11207, 112, 'Can you deliver this to my hotel?', 'Bạn có thể giao món này tới khách sạn không?', '/kən ju dɪˈlɪvər ðɪs tə maɪ hoʊˈtɛl/', '', 'PRACTICE_SENTENCE'),
(11208, 112, 'It is the City Hotel. How long does delivery take?', 'Là khách sạn City. Giao hàng mất bao lâu?', '/ɪt ɪz ðə ˈsɪti hoʊˈtɛl. haʊ lɔŋ dɪz dɪˈlɪvəri teɪk/', '', 'PRACTICE_SENTENCE'),
(11209, 112, 'How can I track the order?', 'Tôi theo dõi đơn hàng bằng cách nào?', '/haʊ kən aɪ træk ðə ˈɔrdər/', '', 'PRACTICE_SENTENCE'),
(11210, 112, 'Thank you. Please send it by email.', 'Cảm ơn. Vui lòng gửi qua email.', '/θæŋk ju. pliz sɛnd ɪt baɪ iˈmeɪl/', '', 'PRACTICE_SENTENCE'),
(11211, 112, 'Of course. Please confirm your email address.', 'Được ạ. Vui lòng xác nhận địa chỉ email.', '/əv kɔrs. pliz kənˈfərm jʊr iˈmeɪl ˈæˌdrɛs/', '', 'PRACTICE_SENTENCE'),
(11212, 112, 'Is there someone who can receive the package?', 'Có người có thể nhận kiện hàng không?', '/ɪz ðɛr ˈsəmˌwən hu kən rɪˈsiv ðə ˈpækɪʤ/', '', 'PRACTICE_SENTENCE'),
(11213, 112, 'Please include your phone number with the address.', 'Vui lòng ghi số điện thoại cùng địa chỉ.', '/pliz ˌɪnˈklud jʊr foʊn ˈnəmbər wɪθ ðə ˈæˌdrɛs/', '', 'PRACTICE_SENTENCE'),
(11307, 113, 'Does this product have a warranty?', 'Sản phẩm này có bảo hành không?', '/dɪz ðɪs ˈprɑdəkt hæv ə ˈwɔrənti/', '', 'PRACTICE_SENTENCE'),
(11308, 113, 'What documents should I keep?', 'Tôi nên giữ giấy tờ nào?', '/wət ˈdɑkjəmənts ʃʊd aɪ kip/', '', 'PRACTICE_SENTENCE'),
(11309, 113, 'Who should I contact if it stops working?', 'Tôi liên hệ ai nếu sản phẩm không hoạt động?', '/hu ʃʊd aɪ ˈkɑnˌtækt ɪf ɪt stɑps ˈwərkɪŋ/', '', 'PRACTICE_SENTENCE'),
(11310, 113, 'Thank you for explaining.', 'Cảm ơn bạn đã giải thích.', '/θæŋk ju fər ɪkˈspleɪnɪŋ/', '', 'PRACTICE_SENTENCE'),
(11311, 113, 'You are welcome. The contact details are on the receipt.', 'Không có gì. Thông tin liên hệ nằm trên biên lai.', '/ju ər ˈwɛlkəm. ðə ˈkɑnˌtækt ˈditeɪlz ər ɔn ðə rɪˈsit/', '', 'PRACTICE_SENTENCE'),
(11312, 113, 'The warranty terms are included in the box.', 'Điều khoản bảo hành nằm trong hộp.', '/ðə ˈwɔrənti tərmz ər ˌɪnˈkludɪd ɪn ðə bɑks/', '', 'PRACTICE_SENTENCE'),
(11313, 113, 'Could you describe the problem with the product?', 'Anh/chị có thể mô tả vấn đề của sản phẩm không?', '/kʊd ju dɪˈskraɪb ðə ˈprɑbləm wɪθ ðə ˈprɑdəkt/', '', 'PRACTICE_SENTENCE'),
(11407, 114, 'I received the wrong item yesterday.', 'Hôm qua tôi nhận nhầm món hàng.', '/aɪ rɪˈsivd ðə rɔŋ ˈaɪtəm ˈjɛstərˌdeɪ/', '', 'PRACTICE_SENTENCE'),
(11408, 114, 'I would like to report a problem with my order.', 'Tôi muốn báo vấn đề với đơn hàng.', '/aɪ wʊd laɪk tə rɪˈpɔrt ə ˈprɑbləm wɪθ maɪ ˈɔrdər/', '', 'PRACTICE_SENTENCE'),
(11409, 114, 'I ordered a blue bag, but received a red one.', 'Tôi đặt túi xanh nhưng nhận túi đỏ.', '/aɪ ˈɔrdərd ə blu bæg, bət rɪˈsivd ə rɛd wən/', '', 'PRACTICE_SENTENCE'),
(11410, 114, 'Thank you. I would prefer the blue bag.', 'Cảm ơn. Tôi muốn chiếc túi xanh.', '/θæŋk ju. aɪ wʊd prɪˈfər ðə blu bæg/', '', 'PRACTICE_SENTENCE'),
(11411, 114, 'I will check whether we can arrange an exchange.', 'Tôi sẽ kiểm tra xem có thể sắp xếp đổi hàng không.', '/aɪ wɪl ʧɛk ˈwɛðər wi kən əreɪnʤ ən ɪksˈʧeɪnʤ/', '', 'PRACTICE_SENTENCE'),
(11412, 114, 'Thank you for bringing this to our attention.', 'Cảm ơn anh/chị đã thông báo vấn đề này.', '/θæŋk ju fər ˈbrɪŋɪŋ ðɪs tə ɑr əˈtɛnʃən/', '', 'PRACTICE_SENTENCE'),
(11413, 114, 'I will update you as soon as I have more information.', 'Tôi sẽ cập nhật ngay khi có thêm thông tin.', '/aɪ wɪl ˈəpˌdeɪt ju ɛz sun ɛz aɪ hæv mɔr ˌɪnˌfɔrˈmeɪʃən/', '', 'PRACTICE_SENTENCE'),
(11507, 115, 'Hello. I am calling about my order.', 'Xin chào. Tôi gọi để hỏi về đơn hàng.', '/hɛˈloʊ. aɪ æm ˈkɔlɪŋ əˈbaʊt maɪ ˈɔrdər/', '', 'PRACTICE_SENTENCE'),
(11508, 115, 'It is A102. My name is Grace.', 'Mã là A102. Tôi tên Grace.', '/ɪt ɪz ə wən ˈziroʊ tu. maɪ neɪm ɪz greɪs/', '', 'PRACTICE_SENTENCE'),
(11509, 115, 'G-R-A-C-E. Can you check the delivery status?', 'G-R-A-C-E. Bạn kiểm tra trạng thái giao giúp tôi nhé?', '/ʤi ɑr eɪ si i. kən ju ʧɛk ðə dɪˈlɪvəri ˈstætəs/', '', 'PRACTICE_SENTENCE'),
(11510, 115, 'Of course. I will wait.', 'Được. Tôi sẽ chờ.', '/əv kɔrs. aɪ wɪl weɪt/', '', 'PRACTICE_SENTENCE'),
(11511, 115, 'Thank you for waiting. I have found your order.', 'Cảm ơn đã chờ. Tôi đã tìm thấy đơn hàng.', '/θæŋk ju fər ˈweɪtɪŋ. aɪ hæv faʊnd jʊr ˈɔrdər/', '', 'PRACTICE_SENTENCE'),
(11512, 115, 'Could you speak a little more slowly?', 'Anh/chị nói chậm hơn một chút được không?', '/kʊd ju spik ə ˈlɪtəl mɔr sˈloʊli/', '', 'PRACTICE_SENTENCE'),
(11513, 115, 'Let me repeat the details to make sure they are correct.', 'Để tôi nhắc lại thông tin để chắc chắn đã đúng.', '/lɛt mi rɪˈpit ðə ˈditeɪlz tə meɪk ʃʊr ðeɪ ər kərˈɛkt/', '', 'PRACTICE_SENTENCE'),
(11607, 116, 'I would like to book a consultation.', 'Tôi muốn đặt lịch tư vấn.', '/aɪ wʊd laɪk tə bʊk ə ˌkɑnsəlˈteɪʃən/', '', 'PRACTICE_SENTENCE'),
(11608, 116, 'Friday morning would be good.', 'Sáng thứ Sáu thì phù hợp.', '/ˈfraɪˌdeɪ ˈmɔrnɪŋ wʊd bi gʊd/', '', 'PRACTICE_SENTENCE'),
(11609, 116, 'Great. Can you confirm it in writing?', 'Tốt. Bạn xác nhận bằng văn bản được không?', '/greɪt. kən ju kənˈfərm ɪt ɪn ˈraɪtɪŋ/', '', 'PRACTICE_SENTENCE'),
(11610, 116, 'Thank you. I will check my email.', 'Cảm ơn. Tôi sẽ kiểm tra email.', '/θæŋk ju. aɪ wɪl ʧɛk maɪ iˈmeɪl/', '', 'PRACTICE_SENTENCE'),
(11611, 116, 'We look forward to seeing you.', 'Chúng tôi mong được gặp anh/chị.', '/wi lʊk ˈfɔrwərd tə siɪŋ ju/', '', 'PRACTICE_SENTENCE'),
(11612, 116, 'Would you prefer to meet in person or online?', 'Anh/chị muốn gặp trực tiếp hay trực tuyến?', '/wʊd ju prɪˈfər tə mit ɪn ˈpərsən ər ˈɔnˌlaɪn/', '', 'PRACTICE_SENTENCE'),
(11613, 116, 'Please let us know if you need to change the appointment.', 'Vui lòng báo nếu anh/chị cần đổi lịch hẹn.', '/pliz lɛt ˈjuˈɛs noʊ ɪf ju nid tə ʧeɪnʤ ðə əˈpɔɪntmənt/', '', 'PRACTICE_SENTENCE'),
(11707, 117, 'Where do I enter my discount code?', 'Tôi nhập mã giảm giá ở đâu?', '/wɛr du aɪ ˈɛnər maɪ ˈdɪskaʊnt koʊd/', '', 'PRACTICE_SENTENCE'),
(11708, 117, 'I entered it, but it does not work.', 'Tôi nhập rồi nhưng mã không hoạt động.', '/aɪ ˈɛnərd ɪt, bət ɪt dɪz nɑt wərk/', '', 'PRACTICE_SENTENCE'),
(11709, 117, 'The code is still valid. Why was it rejected?', 'Mã vẫn còn hạn. Vì sao bị từ chối?', '/ðə koʊd ɪz stɪl ˈvælɪd. waɪ wɑz ɪt rɪˈʤɛktɪd/', '', 'PRACTICE_SENTENCE'),
(11710, 117, 'I see. Could you show me which items are included?', 'Tôi hiểu. Bạn chỉ cho tôi những món được áp dụng nhé?', '/aɪ si. kʊd ju ʃoʊ mi wɪʧ ˈaɪtəmz ər ˌɪnˈkludɪd/', '', 'PRACTICE_SENTENCE'),
(11711, 117, 'Of course. I will send you the list.', 'Được ạ. Tôi sẽ gửi danh sách.', '/əv kɔrs. aɪ wɪl sɛnd ju ðə lɪst/', '', 'PRACTICE_SENTENCE'),
(11712, 117, 'Please check that there are no spaces in the code.', 'Vui lòng kiểm tra mã không có khoảng trắng.', '/pliz ʧɛk ðət ðɛr ər noʊ ˈspeɪsɪz ɪn ðə koʊd/', '', 'PRACTICE_SENTENCE'),
(11713, 117, 'Can you tell me which error message you see?', 'Anh/chị cho tôi biết thông báo lỗi đang thấy được không?', '/kən ju tɛl mi wɪʧ ˈɛrər ˈmɛsɪʤ ju si/', '', 'PRACTICE_SENTENCE'),
(20103, 201, 'May I see your passport, please?', 'Cho tôi xem hộ chiếu nhé?', '/meɪ aɪ si jʊr ˈpæˌspɔrt, pliz/', '', 'PRACTICE_SENTENCE'),
(20104, 201, 'Here is my passport.', 'Đây là hộ chiếu của tôi.', '/hir ɪz maɪ ˈpæˌspɔrt/', '', 'PRACTICE_SENTENCE'),
(20105, 201, 'What is the purpose of your visit?', 'Mục đích chuyến đi của bạn là gì?', '/wət ɪz ðə ˈpərpəs əv jʊr ˈvɪzɪt/', '', 'PRACTICE_SENTENCE'),
(20106, 201, 'I am here for a vacation.', 'Tôi đến đây để du lịch.', '/aɪ æm hir fər ə veɪˈkeɪʃən/', '', 'PRACTICE_SENTENCE'),
(20107, 201, 'How long will you stay?', 'Bạn sẽ ở bao lâu?', '/haʊ lɔŋ wɪl ju steɪ/', '', 'PRACTICE_SENTENCE'),
(20108, 201, 'I will stay for five days.', 'Tôi sẽ ở trong năm ngày.', '/aɪ wɪl steɪ fər faɪv deɪz/', '', 'PRACTICE_SENTENCE'),
(20109, 201, 'Enjoy your trip!', 'Chúc bạn một chuyến đi vui vẻ!', '/ˌɛnˈʤɔɪ jʊr trɪp/', '', 'PRACTICE_SENTENCE'),
(20110, 201, 'Thank you very much.', 'Cảm ơn rất nhiều.', '/θæŋk ju ˈvɛri məʧ/', '', 'PRACTICE_SENTENCE'),
(20203, 202, 'I would like to check in, please.', 'Tôi muốn làm thủ tục nhận phòng.', '/aɪ wʊd laɪk tə ʧɛk ɪn, pliz/', '', 'PRACTICE_SENTENCE'),
(20204, 202, 'Could you confirm my booking?', 'Bạn xác nhận đặt phòng của tôi giúp nhé?', '/kʊd ju kənˈfərm maɪ ˈbʊkɪŋ/', '', 'PRACTICE_SENTENCE'),
(20205, 202, 'What time is breakfast served?', 'Bữa sáng được phục vụ lúc mấy giờ?', '/wət taɪm ɪz ˈbrɛkfəst sərvd/', '', 'PRACTICE_SENTENCE'),
(20206, 202, 'Where can I find the lift?', 'Tôi tìm thang máy ở đâu?', '/wɛr kən aɪ faɪnd ðə lɪft/', '', 'PRACTICE_SENTENCE'),
(20207, 202, 'Could I have an extra towel, please?', 'Cho tôi xin thêm khăn tắm nhé?', '/kʊd aɪ hæv ən ˈɛkstrə taʊəl, pliz/', '', 'PRACTICE_SENTENCE'),
(20208, 202, 'The air conditioning does not seem to work.', 'Điều hòa có vẻ không hoạt động.', '/ðə ɛr kənˈdɪʃənɪŋ dɪz nɑt sim tə wərk/', '', 'PRACTICE_SENTENCE'),
(20209, 202, 'Could someone help me with my luggage?', 'Có ai giúp tôi với hành lý được không?', '/kʊd ˈsəmˌwən hɛlp mi wɪθ maɪ ˈləgɪʤ/', '', 'PRACTICE_SENTENCE'),
(20210, 202, 'What time do I need to check out?', 'Tôi cần trả phòng lúc mấy giờ?', '/wət taɪm du aɪ nid tə ʧɛk aʊt/', '', 'PRACTICE_SENTENCE'),
(20303, 203, 'Hi! Are you ready to order?', 'Chào bạn! Bạn đã sẵn sàng gọi món chưa?', '/haɪ! ər ju ˈrɛdi tə ˈɔrdər/', '', 'PRACTICE_SENTENCE'),
(20304, 203, 'Of course. Would you like something to drink?', 'Được chứ. Bạn muốn uống gì không?', '/əv kɔrs. wʊd ju laɪk ˈsəmθɪŋ tə drɪŋk/', '', 'PRACTICE_SENTENCE'),
(20305, 203, 'Water, please.', 'Cho tôi nước lọc nhé.', '/ˈwɔtər, pliz/', '', 'PRACTICE_SENTENCE'),
(20306, 203, 'Would you like to pay by cash or card?', 'Bạn muốn thanh toán tiền mặt hay thẻ?', '/wʊd ju laɪk tə peɪ baɪ kæʃ ər kɑrd/', '', 'PRACTICE_SENTENCE'),
(20307, 203, 'Certainly. Thank you and have a nice day!', 'Được chứ. Cảm ơn và chúc bạn một ngày tốt lành!', '/ˈsərtənli. θæŋk ju ənd hæv ə nis deɪ/', '', 'PRACTICE_SENTENCE'),
(20308, 203, 'Thank you. You too!', 'Cảm ơn. Bạn cũng vậy nhé!', '/θæŋk ju. ju tu/', '', 'PRACTICE_SENTENCE'),
(20309, 203, 'Could you recommend a local dish?', 'Bạn gợi ý món ăn địa phương được không?', '/kʊd ju ˌrɛkəˈmɛnd ə ˈloʊkəl dɪʃ/', '', 'PRACTICE_SENTENCE'),
(20310, 203, 'Could I have the bill, please?', 'Cho tôi xin hóa đơn nhé?', '/kʊd aɪ hæv ðə bɪl, pliz/', '', 'PRACTICE_SENTENCE'),
(20403, 204, 'Could you help me find this address?', 'Bạn giúp tôi tìm địa chỉ này được không?', '/kʊd ju hɛlp mi faɪnd ðɪs ˈæˌdrɛs/', '', 'PRACTICE_SENTENCE'),
(20404, 204, 'Should I turn left or right at the next street?', 'Tôi nên rẽ trái hay phải ở đường tiếp theo?', '/ʃʊd aɪ tərn lɛft ər raɪt æt ðə nɛkst strit/', '', 'PRACTICE_SENTENCE'),
(20405, 204, 'Which bus goes to the city centre?', 'Xe buýt nào đi đến trung tâm thành phố?', '/wɪʧ bəs goʊz tə ðə ˈsɪti ˈsɛntər/', '', 'PRACTICE_SENTENCE'),
(20406, 204, 'Where can I buy a ticket?', 'Tôi mua vé ở đâu?', '/wɛr kən aɪ baɪ ə ˈtɪkɪt/', '', 'PRACTICE_SENTENCE'),
(20407, 204, 'Do I need to change trains?', 'Tôi có cần đổi tàu không?', '/du aɪ nid tə ʧeɪnʤ treɪnz/', '', 'PRACTICE_SENTENCE'),
(20408, 204, 'How many stops are there before my destination?', 'Còn bao nhiêu trạm trước khi đến nơi?', '/haʊ ˈmɛni stɑps ər ðɛr ˌbiˈfɔr maɪ ˌdɛstɪˈneɪʃən/', '', 'PRACTICE_SENTENCE'),
(20409, 204, 'Could you let me know when we arrive?', 'Bạn báo cho tôi khi đến nơi nhé?', '/kʊd ju lɛt mi noʊ wɪn wi əraɪv/', '', 'PRACTICE_SENTENCE'),
(20410, 204, 'I think I have taken the wrong bus.', 'Tôi nghĩ mình đã đi nhầm xe buýt.', '/aɪ θɪŋk aɪ hæv ˈteɪkən ðə rɔŋ bəs/', '', 'PRACTICE_SENTENCE'),
(20507, 205, 'Hello. Do you need directions?', 'Xin chào. Bạn cần chỉ đường không?', '/hɛˈloʊ. du ju nid dɪˈrɛkʃɪnz/', '', 'PRACTICE_SENTENCE'),
(20508, 205, 'Are you travelling by metro?', 'Bạn đi bằng tàu điện ngầm phải không?', '/ər ju ˈtrævəlɪŋ baɪ ˈmɛˌtroʊ/', '', 'PRACTICE_SENTENCE'),
(20509, 205, 'Would you like to walk from the station?', 'Bạn có muốn đi bộ từ nhà ga không?', '/wʊd ju laɪk tə wɔk frəm ðə ˈsteɪʃən/', '', 'PRACTICE_SENTENCE'),
(20510, 205, 'You can check the route on your map.', 'Bạn có thể xem đường đi trên bản đồ.', '/ju kən ʧɛk ðə rut ɔn jʊr mæp/', '', 'PRACTICE_SENTENCE'),
(20511, 205, 'Thank you for your help.', 'Cảm ơn bạn đã giúp đỡ.', '/θæŋk ju fər jʊr hɛlp/', '', 'PRACTICE_SENTENCE'),
(20512, 205, 'Which exit should I take at the station?', 'Tôi nên đi lối ra nào ở nhà ga?', '/wɪʧ ˈɛksət ʃʊd aɪ teɪk æt ðə ˈsteɪʃən/', '', 'PRACTICE_SENTENCE'),
(20513, 205, 'Could you point out the route on this map?', 'Bạn chỉ đường trên bản đồ này giúp tôi nhé?', '/kʊd ju pɔɪnt aʊt ðə rut ɔn ðɪs mæp/', '', 'PRACTICE_SENTENCE'),
(20607, 206, 'Welcome to the Louvre. How can I help?', 'Chào mừng đến Louvre. Tôi có thể giúp gì?', '/ˈwɛlkəm tə ðə ˈluvrə. haʊ kən aɪ hɛlp/', '', 'PRACTICE_SENTENCE'),
(20608, 206, 'Have you already purchased a ticket?', 'Bạn đã mua vé chưa?', '/hæv ju ɔˈrɛdi ˈpərʧəst ə ˈtɪkɪt/', '', 'PRACTICE_SENTENCE'),
(20609, 206, 'Do you have any questions about the museum rules?', 'Bạn có câu hỏi gì về quy định bảo tàng không?', '/du ju hæv ˈɛni kˈwɛsʧənz əˈbaʊt ðə mˈjuziəm rulz/', '', 'PRACTICE_SENTENCE'),
(20610, 206, 'Please check the signs in each gallery.', 'Hãy xem biển hướng dẫn trong từng phòng trưng bày.', '/pliz ʧɛk ðə saɪnz ɪn iʧ ˈgæləri/', '', 'PRACTICE_SENTENCE'),
(20611, 206, 'Thank you. I will follow the rules.', 'Cảm ơn. Tôi sẽ tuân thủ quy định.', '/θæŋk ju. aɪ wɪl ˈfɑloʊ ðə rulz/', '', 'PRACTICE_SENTENCE'),
(20612, 206, 'Where can I leave my backpack during the visit?', 'Tôi có thể gửi ba lô ở đâu trong lúc tham quan?', '/wɛr kən aɪ liv maɪ ˈbækˌpæk ˈdʊrɪŋ ðə ˈvɪzɪt/', '', 'PRACTICE_SENTENCE'),
(20613, 206, 'Could you tell me where the information desk is?', 'Bạn cho tôi biết quầy thông tin ở đâu nhé?', '/kʊd ju tɛl mi wɛr ðə ˌɪnˌfɔrˈmeɪʃən dɛsk ɪz/', '', 'PRACTICE_SENTENCE'),
(20707, 207, 'Welcome. Would you like information about our tours?', 'Xin chào. Bạn muốn tìm hiểu về các tour không?', '/ˈwɛlkəm. wʊd ju laɪk ˌɪnˌfɔrˈmeɪʃən əˈbaʊt ɑr tʊrz/', '', 'PRACTICE_SENTENCE'),
(20708, 207, 'Do you have any questions before booking?', 'Bạn có câu hỏi nào trước khi đặt tour không?', '/du ju hæv ˈɛni kˈwɛsʧənz ˌbiˈfɔr ˈbʊkɪŋ/', '', 'PRACTICE_SENTENCE'),
(20709, 207, 'What would you like to learn about the Colosseum?', 'Bạn muốn tìm hiểu gì về Colosseum?', '/wət wʊd ju laɪk tə lərn əˈbaʊt ðə ˌkɑləˈsiəm/', '', 'PRACTICE_SENTENCE'),
(20710, 207, 'Our guide will explain the history during the tour.', 'Hướng dẫn viên sẽ giải thích lịch sử trong tour.', '/ɑr gaɪd wɪl ɪkˈspleɪn ðə ˈhɪstəri ˈdʊrɪŋ ðə tʊr/', '', 'PRACTICE_SENTENCE'),
(20711, 207, 'Thank you. That sounds interesting.', 'Cảm ơn. Nghe rất thú vị.', '/θæŋk ju. ðət saʊnz ˈɪntəˌrɛstɪŋ/', '', 'PRACTICE_SENTENCE'),
(20712, 207, 'Where does the group meet before the tour?', 'Đoàn tập trung ở đâu trước khi bắt đầu tour?', '/wɛr dɪz ðə grup mit ˌbiˈfɔr ðə tʊr/', '', 'PRACTICE_SENTENCE'),
(20713, 207, 'May I ask a question about this part of the building?', 'Tôi có thể hỏi về phần công trình này không?', '/meɪ aɪ æsk ə kˈwɛʃən əˈbaʊt ðɪs pɑrt əv ðə ˈbɪldɪŋ/', '', 'PRACTICE_SENTENCE'),
(20807, 208, 'Welcome. Is this your first visit?', 'Xin chào. Đây là lần đầu bạn đến phải không?', '/ˈwɛlkəm. ɪz ðɪs jʊr fərst ˈvɪzɪt/', '', 'PRACTICE_SENTENCE'),
(20808, 208, 'Are you entering this building?', 'Bạn có định vào tòa nhà này không?', '/ər ju ˈɛnərɪŋ ðɪs ˈbɪldɪŋ/', '', 'PRACTICE_SENTENCE'),
(20809, 208, 'Do you have a question about photography?', 'Bạn có câu hỏi về việc chụp ảnh không?', '/du ju hæv ə kˈwɛʃən əˈbaʊt fəˈtɑgrəfi/', '', 'PRACTICE_SENTENCE'),
(20810, 208, 'Please look for signs before taking photos.', 'Hãy xem biển báo trước khi chụp ảnh.', '/pliz lʊk fər saɪnz ˌbiˈfɔr ˈteɪkɪŋ ˈfoʊˌtoʊz/', '', 'PRACTICE_SENTENCE'),
(20811, 208, 'Thank you. I will be respectful.', 'Cảm ơn. Tôi sẽ ứng xử lịch sự.', '/θæŋk ju. aɪ wɪl bi rɪˈspɛktfəl/', '', 'PRACTICE_SENTENCE'),
(20812, 208, 'Is this area open to visitors?', 'Khu vực này có mở cho khách tham quan không?', '/ɪz ðɪs ˈɛriə ˈoʊpən tə ˈvɪzɪtərz/', '', 'PRACTICE_SENTENCE'),
(20813, 208, 'Please let me know if I am doing anything incorrectly.', 'Vui lòng nhắc nếu tôi làm điều gì chưa đúng.', '/pliz lɛt mi noʊ ɪf aɪ æm duɪŋ ˈɛniˌθɪŋ ˌɪnkərˈɛktli/', '', 'PRACTICE_SENTENCE'),
(20907, 209, 'Hello. Are you looking for a place to take photos?', 'Xin chào. Bạn đang tìm nơi chụp ảnh phải không?', '/hɛˈloʊ. ər ju ˈlʊkɪŋ fər ə pleɪs tə teɪk ˈfoʊˌtoʊz/', '', 'PRACTICE_SENTENCE'),
(20908, 209, 'This spot has a nice view.', 'Chỗ này có cảnh đẹp.', '/ðɪs spɑt həz ə nis vju/', '', 'PRACTICE_SENTENCE'),
(20909, 209, 'How would you like me to frame the photo?', 'Bạn muốn tôi lấy khung hình như thế nào?', '/haʊ wʊd ju laɪk mi tə freɪm ðə ˈfoʊˌtoʊ/', '', 'PRACTICE_SENTENCE'),
(20910, 209, 'Here is your phone. I hope you like the photo.', 'Điện thoại của bạn đây. Hy vọng bạn thích ảnh.', '/hir ɪz jʊr foʊn. aɪ hoʊp ju laɪk ðə ˈfoʊˌtoʊ/', '', 'PRACTICE_SENTENCE'),
(20911, 209, 'Thank you so much for your help.', 'Cảm ơn bạn rất nhiều.', '/θæŋk ju soʊ məʧ fər jʊr hɛlp/', '', 'PRACTICE_SENTENCE'),
(20912, 209, 'Could you take one more photo, please?', 'Bạn chụp thêm một tấm nữa giúp tôi nhé?', '/kʊd ju teɪk wən mɔr ˈfoʊˌtoʊ, pliz/', '', 'PRACTICE_SENTENCE'),
(20913, 209, 'Would you like me to take a photo of you as well?', 'Bạn có muốn tôi chụp giúp bạn một tấm không?', '/wʊd ju laɪk mi tə teɪk ə ˈfoʊˌtoʊ əv ju ɛz wɛl/', '', 'PRACTICE_SENTENCE'),
(21007, 210, 'Welcome. What kind of gift would you like?', 'Xin chào. Bạn muốn mua loại quà nào?', '/ˈwɛlkəm. wət kaɪnd əv gɪft wʊd ju laɪk/', '', 'PRACTICE_SENTENCE'),
(21008, 210, 'Would you like to know where this item was made?', 'Bạn có muốn biết món này được làm ở đâu không?', '/wʊd ju laɪk tə noʊ wɛr ðɪs ˈaɪtəm wɑz meɪd/', '', 'PRACTICE_SENTENCE'),
(21009, 210, 'Do you have a question about the pattern?', 'Bạn có câu hỏi về họa tiết không?', '/du ju hæv ə kˈwɛʃən əˈbaʊt ðə ˈpætərn/', '', 'PRACTICE_SENTENCE'),
(21010, 210, 'I can explain its meaning and show you other designs.', 'Tôi có thể giải thích ý nghĩa và cho bạn xem các mẫu khác.', '/aɪ kən ɪkˈspleɪn ɪts ˈminɪŋ ənd ʃoʊ ju ˈəðər dɪˈzaɪnz/', '', 'PRACTICE_SENTENCE'),
(21011, 210, 'Thank you. I would like to see the other designs.', 'Cảm ơn. Tôi muốn xem các mẫu khác.', '/θæŋk ju. aɪ wʊd laɪk tə si ðə ˈəðər dɪˈzaɪnz/', '', 'PRACTICE_SENTENCE'),
(21012, 210, 'Do you have something that is easy to carry?', 'Bạn có món nào dễ mang theo không?', '/du ju hæv ˈsəmθɪŋ ðət ɪz ˈizi tə ˈkɛri/', '', 'PRACTICE_SENTENCE'),
(21013, 210, 'Could you show me a few smaller gifts?', 'Bạn cho tôi xem vài món quà nhỏ hơn nhé?', '/kʊd ju ʃoʊ mi ə fju sˈmɔlər gɪfts/', '', 'PRACTICE_SENTENCE'),
(21107, 211, 'Hello. Are you interested in this cup?', 'Xin chào. Bạn thích chiếc cốc này phải không?', '/hɛˈloʊ. ər ju ˈɪntəˌrɛstɪd ɪn ðɪs kəp/', '', 'PRACTICE_SENTENCE'),
(21108, 211, 'Would you like to know about the material?', 'Bạn muốn tìm hiểu về chất liệu không?', '/wʊd ju laɪk tə noʊ əˈbaʊt ðə məˈtɪriəl/', '', 'PRACTICE_SENTENCE'),
(21109, 211, 'Do you need advice on caring for it?', 'Bạn cần lời khuyên về cách bảo quản không?', '/du ju nid ədˈvaɪs ɔn ˈkɛrɪŋ fər ɪt/', '', 'PRACTICE_SENTENCE'),
(21110, 211, 'I can give you the care instructions.', 'Tôi có thể đưa bạn hướng dẫn bảo quản.', '/aɪ kən gɪv ju ðə kɛr ˌɪnˈstrəkʃənz/', '', 'PRACTICE_SENTENCE'),
(21111, 211, 'Yes, please. Thank you.', 'Có nhé. Cảm ơn.', '/jɛs, pliz. θæŋk ju/', '', 'PRACTICE_SENTENCE'),
(21112, 211, 'Was this made by a local artist?', 'Món này do nghệ nhân địa phương làm phải không?', '/wɑz ðɪs meɪd baɪ ə ˈloʊkəl ˈɑrtɪst/', '', 'PRACTICE_SENTENCE'),
(21113, 211, 'Is it safe to wash this by hand?', 'Tôi có thể rửa món này bằng tay không?', '/ɪz ɪt seɪf tə wɑʃ ðɪs baɪ hænd/', '', 'PRACTICE_SENTENCE'),
(21207, 212, 'Hello. Do you like this magnet?', 'Xin chào. Bạn thích nam châm này phải không?', '/hɛˈloʊ. du ju laɪk ðɪs ˈmægnət/', '', 'PRACTICE_SENTENCE'),
(21208, 212, 'It costs five dollars.', 'Món này giá năm đô la.', '/ɪt kɔsts faɪv ˈdɔlərz/', '', 'PRACTICE_SENTENCE'),
(21209, 212, 'We may have a discount for multiple items.', 'Mua nhiều món có thể được giảm giá.', '/wi meɪ hæv ə ˈdɪskaʊnt fər ˈməltəpəl ˈaɪtəmz/', '', 'PRACTICE_SENTENCE'),
(21210, 212, 'Let me check the price for two.', 'Để tôi kiểm tra giá cho hai chiếc.', '/lɛt mi ʧɛk ðə praɪs fər tu/', '', 'PRACTICE_SENTENCE'),
(21211, 212, 'Thank you. Please let me know the total.', 'Cảm ơn. Bạn báo tổng tiền giúp tôi nhé.', '/θæŋk ju. pliz lɛt mi noʊ ðə ˈtoʊtəl/', '', 'PRACTICE_SENTENCE'),
(21212, 212, 'What would the total be for three magnets?', 'Ba chiếc nam châm thì tổng giá là bao nhiêu?', '/wət wʊd ðə ˈtoʊtəl bi fər θri ˈmægnəts/', '', 'PRACTICE_SENTENCE'),
(21213, 212, 'I understand. Thank you for explaining the price.', 'Tôi hiểu rồi. Cảm ơn đã giải thích về giá.', '/aɪ ˌəndərˈstænd. θæŋk ju fər ɪkˈspleɪnɪŋ ðə praɪs/', '', 'PRACTICE_SENTENCE'),
(21307, 213, 'How would you like to pay?', 'Bạn muốn thanh toán bằng cách nào?', '/haʊ wʊd ju laɪk tə peɪ/', '', 'PRACTICE_SENTENCE'),
(21308, 213, 'Would you prefer to use a card?', 'Bạn muốn dùng thẻ không?', '/wʊd ju prɪˈfər tə juz ə kɑrd/', '', 'PRACTICE_SENTENCE'),
(21309, 213, 'Here is your change. Is everything correct?', 'Đây là tiền thừa của bạn. Mọi thứ đã đúng chưa?', '/hir ɪz jʊr ʧeɪnʤ. ɪz ˈɛvriˌθɪŋ kərˈɛkt/', '', 'PRACTICE_SENTENCE'),
(21310, 213, 'Of course. Let me count it again.', 'Được chứ. Để tôi đếm lại.', '/əv kɔrs. lɛt mi kaʊnt ɪt əˈgɛn/', '', 'PRACTICE_SENTENCE'),
(21311, 213, 'Thank you for checking.', 'Cảm ơn đã kiểm tra.', '/θæŋk ju fər ˈʧɛkɪŋ/', '', 'PRACTICE_SENTENCE'),
(21312, 213, 'Could I have a receipt for this purchase?', 'Cho tôi xin biên lai cho món hàng này nhé?', '/kʊd aɪ hæv ə rɪˈsit fər ðɪs ˈpərʧəs/', '', 'PRACTICE_SENTENCE'),
(21313, 213, 'Please show me the total before I pay.', 'Vui lòng cho tôi xem tổng tiền trước khi thanh toán.', '/pliz ʃoʊ mi ðə ˈtoʊtəl ˌbiˈfɔr aɪ peɪ/', '', 'PRACTICE_SENTENCE'),
(21407, 214, 'Would you like this wrapped?', 'Bạn có muốn gói món này không?', '/wʊd ju laɪk ðɪs ræpt/', '', 'PRACTICE_SENTENCE'),
(21408, 214, 'Are you taking it on a long journey?', 'Bạn sẽ mang nó đi xa phải không?', '/ər ju ˈteɪkɪŋ ɪt ɔn ə lɔŋ ˈʤərni/', '', 'PRACTICE_SENTENCE'),
(21409, 214, 'Would you like to inspect it first?', 'Bạn muốn kiểm tra món đồ trước không?', '/wʊd ju laɪk tə ˌɪnˈspɛkt ɪt fərst/', '', 'PRACTICE_SENTENCE'),
(21410, 214, 'Of course. I will wrap it after you check it.', 'Được chứ. Tôi sẽ gói sau khi bạn kiểm tra.', '/əv kɔrs. aɪ wɪl ræp ɪt ˈæftər ju ʧɛk ɪt/', '', 'PRACTICE_SENTENCE'),
(21411, 214, 'Thank you. That would be helpful.', 'Cảm ơn. Như vậy rất hữu ích.', '/θæŋk ju. ðət wʊd bi ˈhɛlpfəl/', '', 'PRACTICE_SENTENCE'),
(21412, 214, 'Could you put the gifts in separate bags?', 'Bạn để các món quà vào túi riêng giúp tôi nhé?', '/kʊd ju pʊt ðə gɪfts ɪn ˈsɛpərˌeɪt bægz/', '', 'PRACTICE_SENTENCE'),
(21413, 214, 'Will this packaging protect the item during the journey?', 'Cách đóng gói này có bảo vệ món đồ trong chuyến đi không?', '/wɪl ðɪs ˈpækɪʤɪŋ prəˈtɛkt ðə ˈaɪtəm ˈdʊrɪŋ ðə ˈʤərni/', '', 'PRACTICE_SENTENCE'),
(21507, 215, 'Welcome. Your ticket has a timed entry.', 'Xin chào. Vé của bạn có giờ vào cửa cụ thể.', '/ˈwɛlkəm. jʊr ˈtɪkɪt həz ə taɪmd ˈɛntri/', '', 'PRACTICE_SENTENCE'),
(21508, 215, 'Please wait near this entrance. Do you need a guide?', 'Bạn chờ gần lối vào này nhé. Bạn cần hướng dẫn không?', '/pliz weɪt nɪr ðɪs ˈɛntrəns. du ju nid ə gaɪd/', '', 'PRACTICE_SENTENCE'),
(21509, 215, 'You can check the available languages at the desk.', 'Bạn có thể hỏi các ngôn ngữ được hỗ trợ tại quầy.', '/ju kən ʧɛk ðə əˈveɪləbəl ˈlæŋgwɪʤɪz æt ðə dɛsk/', '', 'PRACTICE_SENTENCE'),
(21510, 215, 'Yes, follow the signs along this route.', 'Có, hãy đi theo biển chỉ dẫn dọc tuyến này.', '/jɛs, ˈfɑloʊ ðə saɪnz əˈlɔŋ ðɪs rut/', '', 'PRACTICE_SENTENCE'),
(21511, 215, 'Thank you. I will follow the signs.', 'Cảm ơn. Tôi sẽ đi theo biển chỉ dẫn.', '/θæŋk ju. aɪ wɪl ˈfɑloʊ ðə saɪnz/', '', 'PRACTICE_SENTENCE'),
(21512, 215, 'Where can I check the opening hours for today?', 'Tôi xem giờ mở cửa hôm nay ở đâu?', '/wɛr kən aɪ ʧɛk ðə ˈoʊpənɪŋ aʊərz fər təˈdeɪ/', '', 'PRACTICE_SENTENCE'),
(21513, 215, 'Are there any areas that are closed to visitors?', 'Có khu vực nào không mở cho khách tham quan không?', '/ər ðɛr ˈɛni ˈɛriəz ðət ər kloʊzd tə ˈvɪzɪtərz/', '', 'PRACTICE_SENTENCE'),
(21607, 216, 'Hello. Are you planning to walk this part of the wall?', 'Xin chào. Bạn định đi bộ đoạn tường này à?', '/hɛˈloʊ. ər ju ˈplænɪŋ tə wɔk ðɪs pɑrt əv ðə wɔl/', '', 'PRACTICE_SENTENCE'),
(21608, 216, 'Some parts can be challenging. How much walking do you prefer?', 'Một số đoạn khá khó đi. Bạn muốn đi bộ nhiều không?', '/səm pɑrts kən bi ˈʧælənʤɪŋ. haʊ məʧ ˈwɔkɪŋ du ju prɪˈfər/', '', 'PRACTICE_SENTENCE'),
(21609, 216, 'There are steps here, so take your time.', 'Ở đây có các bậc thang, hãy đi từ từ.', '/ðɛr ər stɛps hir, soʊ teɪk jʊr taɪm/', '', 'PRACTICE_SENTENCE'),
(21610, 216, 'Please ask the staff for the nearest designated rest area.', 'Bạn hỏi nhân viên về khu nghỉ được quy định gần nhất nhé.', '/pliz æsk ðə stæf fər ðə ˈnɪrəst ˈdɛzɪgˌneɪtɪd rɛst ˈɛriə/', '', 'PRACTICE_SENTENCE'),
(21611, 216, 'Thank you. We will take it slowly.', 'Cảm ơn. Chúng tôi sẽ đi chậm.', '/θæŋk ju. wi wɪl teɪk ɪt sˈloʊli/', '', 'PRACTICE_SENTENCE'),
(21612, 216, 'Would you recommend a shorter walking route?', 'Bạn gợi ý một tuyến đi bộ ngắn hơn được không?', '/wʊd ju ˌrɛkəˈmɛnd ə ˈʃɔrtər ˈwɔkɪŋ rut/', '', 'PRACTICE_SENTENCE'),
(21613, 216, 'Where should we meet the guide after our break?', 'Sau lúc nghỉ chúng tôi gặp hướng dẫn viên ở đâu?', '/wɛr ʃʊd wi mit ðə gaɪd ˈæftər ɑr breɪk/', '', 'PRACTICE_SENTENCE'),
(21707, 217, 'Hello. Would you like directions to a viewpoint?', 'Xin chào. Bạn muốn hỏi đường tới điểm ngắm cảnh không?', '/hɛˈloʊ. wʊd ju laɪk dɪˈrɛkʃɪnz tə ə vˈjuˌpɔɪnt/', '', 'PRACTICE_SENTENCE'),
(21708, 217, 'Follow the signs ahead. There can be spray from the falls.', 'Hãy theo biển chỉ dẫn phía trước. Có thể có hơi nước bắn từ thác.', '/ˈfɑloʊ ðə saɪnz əˈhɛd. ðɛr kən bi spreɪ frəm ðə fɔlz/', '', 'PRACTICE_SENTENCE'),
(21709, 217, 'A raincoat may help. Please also check the path signs.', 'Áo mưa có thể hữu ích. Bạn cũng kiểm tra biển báo lối đi nhé.', '/ə ˈreɪnˌkoʊt meɪ hɛlp. pliz ˈɔlsoʊ ʧɛk ðə pæθ saɪnz/', '', 'PRACTICE_SENTENCE'),
(21710, 217, 'Please check the current notices; wet surfaces can be slippery.', 'Vui lòng xem thông báo hiện tại; bề mặt ướt có thể trơn trượt.', '/pliz ʧɛk ðə ˈkɑrənt ˈnoʊtɪsɪz; wɛt ˈsərfəsɪz kən bi sˈlɪpəri/', '', 'PRACTICE_SENTENCE'),
(21711, 217, 'Thank you. I will be careful.', 'Cảm ơn. Tôi sẽ cẩn thận.', '/θæŋk ju. aɪ wɪl bi ˈkɛrfəl/', '', 'PRACTICE_SENTENCE'),
(21712, 217, 'Should we stay behind this railing?', 'Chúng tôi có nên đứng phía sau lan can này không?', '/ʃʊd wi steɪ bɪˈhaɪnd ðɪs ˈreɪlɪŋ/', '', 'PRACTICE_SENTENCE'),
(21713, 217, 'Where can I find the latest safety notices?', 'Tôi tìm thông báo an toàn mới nhất ở đâu?', '/wɛr kən aɪ faɪnd ðə ˈleɪtəst ˈseɪfti ˈnoʊtɪsɪz/', '', 'PRACTICE_SENTENCE'),
(21807, 218, 'Hi. Are you enjoying the park?', 'Chào bạn. Bạn thấy công viên thế nào?', '/haɪ. ər ju ˌɛnˈʤɔɪɪŋ ðə pɑrk/', '', 'PRACTICE_SENTENCE'),
(21808, 218, 'The paths by the lake are lovely.', 'Những lối đi cạnh hồ rất đẹp.', '/ðə pæθs baɪ ðə leɪk ər ˈləvli/', '', 'PRACTICE_SENTENCE'),
(21809, 218, 'There may be a café near the exit. Check your map.', 'Có thể có quán cà phê gần lối ra. Bạn xem bản đồ nhé.', '/ðɛr meɪ bi ə kəˈfeɪ nɪr ðə ˈɛksət. ʧɛk jʊr mæp/', '', 'PRACTICE_SENTENCE'),
(21810, 218, 'It depends on which exit you choose. I can show you on the map.', 'Còn tùy lối ra bạn chọn. Tôi có thể chỉ trên bản đồ.', '/ɪt dɪˈpɛndz ɔn wɪʧ ˈɛksət ju ʧuz. aɪ kən ʃoʊ ju ɔn ðə mæp/', '', 'PRACTICE_SENTENCE'),
(21811, 218, 'Thank you. That would be helpful.', 'Cảm ơn. Như vậy rất hữu ích.', '/θæŋk ju. ðət wʊd bi ˈhɛlpfəl/', '', 'PRACTICE_SENTENCE'),
(21812, 218, 'Is this path suitable for a short walk?', 'Lối này có phù hợp để đi dạo ngắn không?', '/ɪz ðɪs pæθ ˈsutəbəl fər ə ʃɔrt wɔk/', '', 'PRACTICE_SENTENCE'),
(21813, 218, 'Which exit is closest to the subway station?', 'Lối ra nào gần ga tàu điện ngầm nhất?', '/wɪʧ ˈɛksət ɪz ˈkloʊsəst tə ðə ˈsəbˌweɪ ˈsteɪʃən/', '', 'PRACTICE_SENTENCE'),
(21907, 219, 'Welcome. What would you like to drink?', 'Xin chào. Bạn muốn uống gì?', '/ˈwɛlkəm. wət wʊd ju laɪk tə drɪŋk/', '', 'PRACTICE_SENTENCE'),
(21908, 219, 'Our local coffee is popular. How would you like it?', 'Cà phê địa phương của chúng tôi rất được ưa chuộng. Bạn muốn dùng thế nào?', '/ɑr ˈloʊkəl ˈkɔfi ɪz ˈpɑpjələr. haʊ wʊd ju laɪk ɪt/', '', 'PRACTICE_SENTENCE'),
(21909, 219, 'Of course. For here or to take away?', 'Được nhé. Bạn dùng tại chỗ hay mang đi?', '/əv kɔrs. fər hir ər tə teɪk əˈweɪ/', '', 'PRACTICE_SENTENCE'),
(21910, 219, 'Here you are. Enjoy your coffee!', 'Của bạn đây. Chúc bạn uống ngon miệng!', '/hir ju ər. ˌɛnˈʤɔɪ jʊr ˈkɔfi/', '', 'PRACTICE_SENTENCE'),
(21911, 219, 'Thank you. Have a nice day!', 'Cảm ơn. Chúc bạn một ngày tốt lành!', '/θæŋk ju. hæv ə nis deɪ/', '', 'PRACTICE_SENTENCE'),
(21912, 219, 'Would you recommend a hot or cold drink?', 'Bạn gợi ý đồ uống nóng hay lạnh?', '/wʊd ju ˌrɛkəˈmɛnd ə hɑt ər koʊld drɪŋk/', '', 'PRACTICE_SENTENCE'),
(21913, 219, 'Could I have a lid for my cup, please?', 'Cho tôi xin nắp cốc nhé?', '/kʊd aɪ hæv ə lɪd fər maɪ kəp, pliz/', '', 'PRACTICE_SENTENCE'),
(22007, 220, 'Would you like to order this dish?', 'Bạn muốn gọi món này không?', '/wʊd ju laɪk tə ˈɔrdər ðɪs dɪʃ/', '', 'PRACTICE_SENTENCE'),
(22008, 220, 'I am not sure. Do you have any dietary requirements?', 'Tôi chưa chắc. Bạn có yêu cầu đặc biệt về ăn uống không?', '/aɪ æm nɑt ʃʊr. du ju hæv ˈɛni ˈdaɪəˌtɛri rɪkˈwaɪrmənts/', '', 'PRACTICE_SENTENCE'),
(22009, 220, 'Thank you for telling me. We need to confirm the ingredients.', 'Cảm ơn đã cho biết. Chúng tôi cần xác nhận thành phần.', '/θæŋk ju fər ˈtɛlɪŋ mi. wi nid tə kənˈfərm ðə ˌɪnˈgridiənts/', '', 'PRACTICE_SENTENCE'),
(22010, 220, 'Of course. Please wait while I ask the chef.', 'Được nhé. Bạn chờ tôi hỏi đầu bếp.', '/əv kɔrs. pliz weɪt waɪl aɪ æsk ðə ʃɛf/', '', 'PRACTICE_SENTENCE'),
(22011, 220, 'Thank you. Please let me know before I order.', 'Cảm ơn. Vui lòng cho tôi biết trước khi tôi gọi món.', '/θæŋk ju. pliz lɛt mi noʊ ˌbiˈfɔr aɪ ˈɔrdər/', '', 'PRACTICE_SENTENCE'),
(22012, 220, 'Could you tell me all the ingredients in this dish?', 'Bạn cho tôi biết tất cả thành phần của món này nhé?', '/kʊd ju tɛl mi ɔl ðə ˌɪnˈgridiənts ɪn ðɪs dɪʃ/', '', 'PRACTICE_SENTENCE'),
(22013, 220, 'If you cannot confirm it is safe, I will choose another dish.', 'Nếu bạn không xác nhận được an toàn, tôi sẽ chọn món khác.', '/ɪf ju ˈkænɑt kənˈfərm ɪt ɪz seɪf, aɪ wɪl ʧuz əˈnəðər dɪʃ/', '', 'PRACTICE_SENTENCE'),
(22107, 221, 'Welcome. You have arrived before the usual check-in time.', 'Xin chào. Bạn đã đến trước giờ nhận phòng thông thường.', '/ˈwɛlkəm. ju hæv əraɪvd ˌbiˈfɔr ðə ˈjuʒəwəl ʧɛk ɪn taɪm/', '', 'PRACTICE_SENTENCE'),
(22108, 221, 'Let me check. Your room is not ready yet.', 'Để tôi kiểm tra. Phòng của bạn chưa sẵn sàng.', '/lɛt mi ʧɛk. jʊr rum ɪz nɑt ˈrɛdi jɛt/', '', 'PRACTICE_SENTENCE'),
(22109, 221, 'We can check our luggage storage availability.', 'Chúng tôi có thể kiểm tra chỗ giữ hành lý còn trống.', '/wi kən ʧɛk ɑr ˈləgɪʤ ˈstɔrɪʤ əˌveɪləˈbɪlɪti/', '', 'PRACTICE_SENTENCE'),
(22110, 221, 'I will confirm the time after checking with housekeeping.', 'Tôi sẽ xác nhận giờ sau khi hỏi bộ phận buồng phòng.', '/aɪ wɪl kənˈfərm ðə taɪm ˈæftər ˈʧɛkɪŋ wɪθ ˈhaʊˌskipɪŋ/', '', 'PRACTICE_SENTENCE'),
(22111, 221, 'Thank you. Please let me know.', 'Cảm ơn. Vui lòng báo cho tôi nhé.', '/θæŋk ju. pliz lɛt mi noʊ/', '', 'PRACTICE_SENTENCE'),
(22112, 221, 'Could you give me a tag for my luggage?', 'Bạn cho tôi thẻ gửi hành lý được không?', '/kʊd ju gɪv mi ə tæg fər maɪ ˈləgɪʤ/', '', 'PRACTICE_SENTENCE'),
(22113, 221, 'Is there a place where I can wait comfortably?', 'Có nơi nào tôi có thể ngồi chờ thoải mái không?', '/ɪz ðɛr ə pleɪs wɛr aɪ kən weɪt ˈkəmfərtəbli/', '', 'PRACTICE_SENTENCE'),
(22207, 222, 'Hello. Do you need assistance?', 'Xin chào. Bạn cần giúp đỡ không?', '/hɛˈloʊ. du ju nid əˈsɪstəns/', '', 'PRACTICE_SENTENCE'),
(22208, 222, 'It is near the information desk. What did you lose?', 'Quầy ở gần bàn thông tin. Bạn mất món gì?', '/ɪt ɪz nɪr ðə ˌɪnˌfɔrˈmeɪʃən dɛsk. wət dɪd ju luz/', '', 'PRACTICE_SENTENCE'),
(22209, 222, 'We can check whether someone has handed it in.', 'Chúng tôi có thể kiểm tra xem có ai đã giao nộp nó không.', '/wi kən ʧɛk ˈwɛðər ˈsəmˌwən həz ˈhændɪd ɪt ɪn/', '', 'PRACTICE_SENTENCE'),
(22210, 222, 'Certainly. Please describe where you last saw it.', 'Được chứ. Hãy mô tả nơi cuối cùng bạn nhìn thấy nó.', '/ˈsərtənli. pliz dɪˈskraɪb wɛr ju læst sɔ ɪt/', '', 'PRACTICE_SENTENCE'),
(22211, 222, 'Thank you. I last saw it near the entrance.', 'Cảm ơn. Lần cuối tôi thấy nó ở gần lối vào.', '/θæŋk ju. aɪ læst sɔ ɪt nɪr ðə ˈɛntrəns/', '', 'PRACTICE_SENTENCE'),
(22212, 222, 'Can I leave my phone number in case you find it?', 'Tôi để lại số điện thoại để liên hệ nếu tìm thấy được không?', '/kən aɪ liv maɪ foʊn ˈnəmbər ɪn keɪs ju faɪnd ɪt/', '', 'PRACTICE_SENTENCE'),
(22213, 222, 'It has a small blue key ring attached to it.', 'Món đó có gắn một móc khóa nhỏ màu xanh.', '/ɪt həz ə smɔl blu ki rɪŋ əˈtæʧt tə ɪt/', '', 'PRACTICE_SENTENCE');
